/* Browser demonstration. All confidentiality and permissions require a server. */
(function () {
  const pages = ['Scope package', 'Contractor pricing', 'Pricing model', 'Invoice preferences', 'Claims & invoices', 'Task progress', 'Business & team', 'Record of Work', 'TMP membership'];
  const models=['Stage/milestone','Progress valuation','Time & materials','Fixed-price invoice'];
  const columns=['item_code','description','category','unit','quantity','unit_cost_ex_gst','markup_percent'];
  const round=n=>Math.round((n+Number.EPSILON)*100)/100;
  const precise=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
  const preferences=(s,pid)=>s.invoicePreferences?.[pid] || {model:models[0],supplier:'',gstRegistered:false,gstNumber:'',dueDays:20,prefix:'DRAFT',terms:'Payment terms to be agreed',taxBasis:'Excluding GST'};
  function invoiceAmounts(d,pref){
    const val=Number(d.amount),prior=Number(d.previous || 0),hours=Number(d.hours || 0),rate=Number(d.rate || 0),materials=Number(d.materials || 0);
    if(![val,prior,hours,rate,materials].every(n=>Number.isFinite(n)&&n>=0&&n<=100000000))throw Error('Enter valid non-negative amounts.');
    let basis=pref.model==='Time & materials'?round(hours*rate+materials):val;
    if(pref.model==='Progress valuation'){if(prior>basis)throw Error('Previously claimed value exceeds cumulative valuation.');basis=round(basis-prior);}
    if(!Number.isFinite(basis)||basis>100000000)throw Error('Amount is too large.');
    const ex=round(pref.gstRegistered&&pref.taxBasis==='Including GST'?basis/1.15:basis),tax=pref.gstRegistered?round(pref.taxBasis==='Including GST'?basis-ex:ex*.15):0;
    return {net:ex,gst:tax,gross:round(ex+tax),basis,prior,valuation:val,hours,rate,materials};
  }
  function parsePricingCSV(text){
    const errors=[],rows=[];let row=[],cell='',quoted=false,closed=false;
    if(text.length>1000000)return {errors:['CSV exceeds 1 MB.'],rows:[]};
    text=text.replace(/^\uFEFF/,'');
    for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'){if(text[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=ch;}else if(ch==='"'&&!cell&&!closed)quoted=true;else if(ch===','||ch==='\n'||ch==='\r'){row.push(cell);cell='';closed=false;if(ch!==','){if(ch==='\r'&&text[i+1]==='\n')i++;if(row.some(v=>v!==''))rows.push(row);row=[];}}else{if(closed||ch==='"')errors.push('Unexpected character after quoted CSV value.');cell+=ch;}}
    if(quoted)errors.push('Unclosed quoted CSV value.');row.push(cell);if(row.some(v=>v!==''))rows.push(row);
    const head=rows.shift() || [];if(head.join(',')!==columns.join(','))errors.push('Header must exactly match the supplied template.');if(rows.length>500)errors.push('Maximum 500 data rows.');
    const seen=new Set(),result=rows.slice(0,500).map((r,i)=>{const x=Object.fromEntries(columns.map((k,j)=>[k,r[j]??'']));const bad=m=>errors.push(`Row ${i+2}: ${m}`);if(r.length!==7)bad('Expected 7 cells.');if(!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,59}$/.test(x.item_code)||seen.has(x.item_code))bad('Invalid or duplicate item code.');seen.add(x.item_code);for(const k of ['description','category','unit'])if(!x[k].trim()||x[k].length>250||/^[=+@\-\t\r]/.test(x[k])||/[\x00-\x08]/.test(x[k]))bad(`Invalid ${k}; formula-like text is not accepted.`);for(const k of ['quantity','unit_cost_ex_gst','markup_percent']){if(!/^\d+(?:\.\d+)?$/.test(x[k].trim()))bad(`Missing or invalid ${k}.`);x[k]=Number(x[k]);if(!Number.isFinite(x[k])||x[k]<0||x[k]>(k==='markup_percent'?1000:1000000))bad(`${k} exceeds bounds.`);}x.cost=round(x.quantity*x.unit_cost_ex_gst);x.selling=round(x.cost*(1+x.markup_percent/100));x.gst=round(x.selling*.15);if(x.selling>100000000)bad('Line total exceeds bounds.');return x;});return {errors:[...new Set(errors)],rows:result};
  }
  const download=(name,text,type='text/plain')=>{const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  const clamp = n => Math.max(0, Math.min(100, Number.isFinite(n) ? n : 0));
  const nzToday = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Pacific/Auckland',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const id = () => 'co-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
  function setup(c) {
    if(!c.store.invoicePreferences || typeof c.store.invoicePreferences!=='object')c.store.invoicePreferences={};
    ['contractorQuotes','claims','tasks','businessProfiles','rowDrafts','documents','inventory','tenderScopes','variations','subscriptions'].forEach(k => { if (!Array.isArray(c.store[k])) c.store[k] = []; });
    return c.projects.find(p => p.id === c.projectId) || c.project || c.projects[2] || c.projects[0];
  }
  const field = (e, name, title, value = '', type = 'text', extra = '') => `<label>${title}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
  function render(page, c) {
    const p = setup(c), e = c.escape, s = c.store, pid = p.id, mine = k => s[k].filter(x => x.projectId === pid);
    const f = (...a) => field(e, ...a);
    let html = `<div class="heading"><div><div class="eyebrow">CONTRACTOR WORKSPACE</div><h1>${e(page)}</h1><p>${e(p.name)} · ${e(pid)}</p></div></div><div class="co-context"><label>Project<select id="co-project">${c.projects.filter(x => x.id === pid || /contractor|build/i.test(x.stage)).map(x => `<option value="${e(x.id)}" ${x.id===pid?'selected':''}>${e(x.name)}</option>`).join('')}</select></label><span class="small">Fictional data · saved in this browser · no authenticated account</span></div>`;
    const visible = x => !Array.isArray(x.visibility) || x.visibility.includes('contractor');
    const scopes = mine('tenderScopes').filter(visible), docs = mine('documents').filter(visible), inventory = mine('inventory').filter(visible);
    const readable = value => typeof value === 'object' && value !== null ? JSON.stringify(value) : String(value ?? '');
    const scopeDetails = x => ['inclusions','exclusions','responsibilities','siteAccess','consentReferences','specification','acceptance','version','status'].filter(k => x[k] !== undefined && x[k] !== '').map(k => `<div><strong>${e(k.replace(/([A-Z])/g,' $1'))}</strong><p>${e(readable(x[k]))}</p></div>`).join('');
    if (page === 'Scope package') html += `<section class="card"><span class="tag amber">Awarded scope review</span><h2>One concise build package</h2><p>Customer: ${e(p.client)} · ${e(p.place)} · ${e(p.model)}</p><div class="co-columns"><div><h3>Included contractor work</h3>${scopes.length ? scopes.map(x=>`<p>${e(x.title || x.name || x.scope || 'Tender scope')} — ${e(x.description || x.requirements || '')}</p>${scopeDetails(x)}`).join('') : '<ul><li>Site establishment and foundation coordination</li><li>Kit erection, structural fixings and weather-tight shell</li><li>Trade coordination and inspection readiness</li><li>Completion checks and construction records</li></ul><p class="small">Illustrative package; replace with the actual awarded tender.</p>'}</div><div><h3>Confirm before starting</h3><ul><li>Signed scope, exclusions and variations</li><li>Approved plans and consent conditions</li><li>Site access, services and delivery readiness</li><li>Inspections, responsibilities and programme</li></ul><p>Kit supply is Shed House’s responsibility only as agreed in the supply contract. Unpriced ground conditions and fit-out require explicit scope confirmation.</p></div></div></section><section class="card"><h2>Project documents</h2>${docs.map(d=>`<p><strong>${e(d.name)}</strong> · ${e(d.status)} · v${e(d.version || 1)} ${/^https:\/\//.test(d.url || '')?`<a href="${e(d.url)}" target="_blank" rel="noopener">Open document</a>`:''}</p>`).join('') || '<p>No shared documents yet. Shed House uploads will appear here.</p>'}</section><section class="card"><h2>Kitset inventory by category</h2>${[...new Set(inventory.map(x=>x.category || 'Uncategorised'))].map(cat=>`<h3>${e(cat)}</h3>${inventory.filter(x=>(x.category || 'Uncategorised')===cat).map(x=>`<p>${e(x.name || x.item || x.description)} · ${e(x.quantity || x.qty || 0)} ${e(x.unit || '')}</p>`).join('')}`).join('') || '<p>No inventory released for this project yet.</p>'}</section>`;
    if (page === 'Contractor pricing') html += `<section class="card co-notice"><h2>Your estimate workspace</h2><p>Quote cost lines are hidden from other role screens in this concept, but browser storage is not secure. Production needs server-enforced project access and separate contractor cost data. An NDA does not provide technical privacy.</p></section><form class="card co-form" id="co-quote"><h2>Add a cost line</h2>${f('description','Description','','text','required maxlength="150"')}${f('qty','Quantity',1,'number','min="0.01" step="0.01" required')}${f('rate','Rate excluding GST (NZD)',0,'number','min="0" step="0.01" required')}<label>Information sharing proposal<select name="sharing"><option value="private">Private internal cost line</option><option value="summary">Share tender total only after review</option><option value="nda">Request NDA review before tender summary</option></select></label><p class="small">No NDA is signed and nothing is sent by this demo.</p><button class="primary">Save cost line</button></form><section class="card"><h2>Estimate cost lines</h2>${mine('contractorQuotes').map(q=>`<div class="co-row"><div><strong>${e(q.description)}</strong><p>${e(q.qty)} × ${c.money(q.rate)} · ${e(q.sharing)}</p></div><strong>${c.money(q.qty*q.rate)}</strong><button class="secondary" data-co-remove="contractorQuotes:${e(q.id)}">Remove</button></div>`).join('') || '<p>No lines added.</p>'}<h3>Total excluding GST: ${c.money(mine('contractorQuotes').reduce((n,q)=>n+q.qty*q.rate,0))}</h3></section>`;
    if (page === 'Claims & invoices') html += `<section class="card"><h2>Draft a stage valuation</h2><p>Prepare a draft only. It is not issued or served as a statutory payment claim. Confirm the contract, valuation and service requirements before use.</p><p><a href="https://www.legislation.govt.nz/act/public/2002/0046/latest/whole.html" target="_blank" rel="noopener">Construction Contracts Act, section 20</a> · <a href="https://www.building.govt.nz/projects-and-consents/why-contracts-are-valuable/construction-contracts-act-2002/other-requirements" target="_blank" rel="noopener">MBIE payment dispute guidance</a></p></section><form class="card co-form" id="co-claim">${f('reference','Contract / work reference','','text','required maxlength="150"')}${f('work','Work and valuation basis','','text','required maxlength="500"')}${f('from','Claim period start','','date','required')}${f('to','Claim period end','','date','required')}${f('valuation','Cumulative work value excluding GST',0,'number','required min="0" step="0.01"')}${f('previous','Previously claimed excluding GST',0,'number','required min="0" step="0.01"')}${f('gst','GST rate (%)',15,'number','required min="0" max="100" step="0.01"')}${f('due','Proposed due date','','date','required')}<button class="primary">Save draft valuation</button></form><section class="card"><h2>Drafts & validation</h2>${mine('claims').map(q=>`<div class="co-row"><div><strong>${e(q.reference)}</strong><p>${e(q.from)} – ${e(q.to)} · due ${e(q.due)}<br>${e(q.work)}<br>Net ${c.money(q.valuation-q.previous)} + GST ${c.money((q.valuation-q.previous)*q.gst/100)}</p><span class="tag amber">Draft · not served</span></div><strong>${c.money((q.valuation-q.previous)*(1+q.gst/100))}</strong><button class="secondary" data-co-invoice="${e(q.id)}">Download draft invoice / valuation</button></div>`).join('') || '<p>No draft claims.</p>'}<h3>Before any statutory claim is issued</h3><ul><li>Identify the construction contract and work / relevant period.</li><li>Show claimed amount, calculation basis and payment due date.</li><li>State it is made under the Construction Contracts Act 2002.</li><li>Accompany it with the current prescribed Form 1 notice and complete appropriate service.</li></ul><p>This checklist does not certify compliance; have the actual claim and current prescribed notice reviewed.</p></section>`;
    if (page === 'Task progress') html += `<form class="card co-form" id="co-task"><h2>Add a scope task</h2>${f('name','Scope task','','text','required maxlength="150"')}${f('plannedHours','Planned hours',40,'number','min="0" required step="0.5"')}${f('actualHours','Hours worked',0,'number','min="0" required step="0.5"')}${f('start','Planned start','','date','required')}${f('end','Planned completion','','date','required')}<label>Default progress measure<select name="mode"><option value="hours">Hours</option><option value="date">Date</option></select></label><button class="primary">Add task</button></form><section class="card"><h2>Scope task progress</h2><p>Hours show effort used; dates show elapsed programme. Neither alone proves work is complete.</p>${mine('tasks').map(t=>{const span=Date.parse(t.end)-Date.parse(t.start), hp=t.plannedHours>0?clamp(t.actualHours/t.plannedHours*100):0, dp=span>0?clamp((Date.now()-Date.parse(t.start))/span*100):0; return `<form class="co-task co-form" data-co-task="${e(t.id)}"><h3>${e(t.name)}</h3><label>Default meter<select name="mode"><option value="hours" ${t.mode==='hours'?'selected':''}>Hours</option><option value="date" ${t.mode==='date'?'selected':''}>Date</option></select></label><div class="co-meters ${t.mode==='date'?'co-date-first':''}"><div>Hours used: ${t.plannedHours>0?Math.round(hp)+'%':'Unplanned'} · ${e(t.actualHours)} / ${e(t.plannedHours)} h<div class="bar"><i style="width:${hp}%"></i></div></div><div>Programme elapsed: ${span>0?Math.round(dp)+'%':'Same-day task'}<div class="bar"><i style="width:${dp}%"></i></div><p>${e(t.start)} → ${e(t.end)}</p></div></div>${f('actualHours','Update hours worked',t.actualHours,'number','min="0" required step="0.5"')}<label><input name="complete" type="checkbox" ${t.complete?'checked':''}> Work completed and checked</label><button class="secondary">Update task</button></form>`;}).join('') || '<p>No tasks yet.</p>'}</section>`;
    if (page === 'Business & team') html += `<form class="card co-form" id="co-person"><h2>Business or subcontractor practitioner</h2>${f('business','Business name','','text','required maxlength="120"')}${f('person','Practitioner name','','text','required maxlength="120"')}${f('scope','Assigned work / trade','','text','required maxlength="200"')}${f('insurance','Insurance policy / holding','','text','maxlength="150"')}${f('insuranceExpiry','Insurance expiry','','date')}${f('lbp','LBP number / licence','','text','maxlength="80"')}${f('licenceClass','Licence class','','text','maxlength="120"')}${f('certificate','Certificate reference','','text','maxlength="200"')}${f('certificateExpiry','Certificate expiry','','date')}<button class="primary">Add team record</button></form><section class="card"><h2>Business & project team</h2><p>Self-declared demo records; verify insurance, licence register and certificates before appointment.</p>${mine('businessProfiles').map(b=>`<article class="co-task"><h3>${e(b.business)} · ${e(b.person)}</h3><p>${e(b.scope)}<br>LBP ${e(b.lbp || 'Not supplied')} · ${e(b.licenceClass || 'Class not supplied')}<br>Insurance: ${e(b.insurance || 'Not supplied')} · expires ${e(b.insuranceExpiry || 'Not supplied')} ${b.insuranceExpiry&&Date.parse(b.insuranceExpiry)<Date.now()?'<span class="tag amber">Check expiry</span>':''}<br>Certificate: ${e(b.certificate || 'Not supplied')} · expires ${e(b.certificateExpiry || 'Not supplied')}</p><a href="https://www.lbp.govt.nz/for-homeowners/find-an-lbp/" target="_blank" rel="noopener">Verify LBP details</a></article>`).join('') || '<p>No team records yet.</p>'}</section>`;
    if (page === 'Record of Work') html += `<section class="card co-notice"><h2>Completion records & payment are separate</h2><p>An LBP must not withhold a Record of Work because payment is outstanding. Track payment separately. Each LBP must supply their Record of Work to the building owner and territorial authority on completion of their restricted building work, using the official prescribed form.</p><p><a href="https://www.lbp.govt.nz/for-lbps/skills-maintenance/codewords/records-of-work/" target="_blank" rel="noopener">Official LBP Record of Work guidance</a> · <a href="https://www.lbp.govt.nz/assets/lbp/documents/forms/memorandum-record-of-building-work.pdf" target="_blank" rel="noopener">Official prescribed ROW form</a> · <a href="https://www.lbp.govt.nz/for-lbps/resources/" target="_blank" rel="noopener">LBP resources</a></p></section><form class="card co-form" id="co-row"><h2>Prepare completion record draft</h2><p>Project and awarded scope populate automatically. Select the practitioner responsible for the work; no signature is generated.</p><label>Practitioner<select name="practitioner" required><option value="">Select a project practitioner</option>${mine('businessProfiles').map(b=>`<option value="${e(b.id)}">${e(b.person)} · ${e(b.scope)}</option>`).join('')}</select></label>${f('projectReference','Project (review)',p.id+' — '+p.name,'text','readonly')}${f('buildingOwner','Building owner (review)',p.client,'text','readonly')}${f('siteAddress','Site address',p.address || '','text','required maxlength="250"')}${f('consentNumber','Building consent reference',scopes.map(x=>readable(x.consentReferences || '')).filter(Boolean).join('; '),'text','required maxlength="250"')}<label>Practitioner involvement<select name="recordType" required><option value="Carried out">Carried out</option><option value="Supervised">Supervised</option></select></label>${f('work','Description of restricted building work',scopes.map(x=>readable(x.inclusions || x.title || x.name || x.scope || '')).filter(Boolean).join('; '),'text','required maxlength="1000"')}${f('completedOn','Work completion date','','date','required')}<label>Payment tracker<select name="payment"><option>Outstanding</option><option>Part paid</option><option>Paid in full</option></select></label><label><input type="checkbox" name="reviewed" required> I reviewed the work description and practitioner details</label><label><input type="checkbox" name="confirmed" required> The practitioner confirms this work is completed</label><button class="primary">Save reviewed draft</button></form><section class="card"><h2>Completion record drafts</h2>${mine('rowDrafts').map(r=>`<article class="co-task"><h3>${e(r.practitioner.person)} · ${e(r.completedOn)}</h3><p>${e(r.work)}<br>LBP ${e(r.practitioner.lbp || 'Missing — complete before official form')}<br>Payment: ${e(r.payment)} · ${r.released?'Shared with customer':'Awaiting release'}</p><p class="small">Draft preparation record, not the official prescribed ROW form.</p><button class="secondary" data-co-download="${e(r.id)}">Download draft text</button> <button class="primary" data-co-release="${e(r.id)}" ${r.released?'disabled':''}>Release reviewed completion draft</button></article>`).join('') || '<p>No completion drafts yet.</p>'}</section>`;
    if (page === 'TMP membership') {
      const fee = s.fees?.contractorMonthly, configured = fee !== null && fee !== undefined && Number.isFinite(Number(fee)) && Number(fee) >= 0;
      html += `<section class="card"><h2>Contractor marketplace membership</h2><p>Join the nationwide Shed House tender network. Registration of interest is a demo only; it does not activate a subscription or charge a payment method.</p><h3>${configured ? `${c.money(Number(fee))} per month excluding GST · ${c.money(Math.round(Number(fee)*115)/100)} including 15% GST` : 'Monthly price has not been set by Shed House'}</h3><p>Proposed terms for review: monthly renewal; cancellation before the next renewal stops future renewals. Effective dates, refunds, verification and final membership terms require Shed House approval before launch. No automatic renewal or billing operates here.</p></section><form class="card co-form" id="co-membership">${f('business','Business name','','text','required maxlength="120"')}${f('email','Business contact email','','email','required maxlength="180"')}<label><input type="checkbox" name="reviewed" required> I reviewed the proposed renewal and cancellation terms</label><button class="primary">Save signup interest</button></form><section class="card"><h2>Signup interests</h2>${s.subscriptions.map(x=>`<p><strong>${e(x.business)}</strong> · ${e(x.email)} · ${e(x.status)} · ${e(x.createdAt?.slice(0,10) || '')}</p>`).join('') || '<p>No signup interest saved.</p>'}</section>`;
    }
    const pref=preferences(s,pid);
    if(page==='Invoice preferences')html+=`<form class="card co-form" id="co-invoice-pref"><h2>Your recurring invoice choices</h2><p>These project preferences populate future drafts. They do not change the contract or issue a payment claim.</p>${f('supplier','Supplier legal name',pref.supplier,'text','required maxlength="160"')}<label>Invoice model<select name="model">${models.map(m=>`<option ${pref.model===m?'selected':''}>${m}</option>`).join('')}</select></label><label><input type="checkbox" name="gstRegistered" ${pref.gstRegistered?'checked':''}> Supplier is GST registered</label>${f('gstNumber','GST registration number (if applicable)',pref.gstNumber,'text','maxlength="40"')}<label>Input tax basis<select name="taxBasis">${['Excluding GST','Including GST'].map(m=>`<option ${pref.taxBasis===m?'selected':''}>${m}</option>`).join('')}</select></label>${f('dueDays','Payment due days',pref.dueDays,'number','required min="0" max="365"')}${f('prefix','Invoice reference prefix',pref.prefix,'text','required pattern="[A-Za-z0-9_-]{1,20}"')}<label>Payment terms<textarea name="terms" maxlength="1000" required>${e(pref.terms)}</textarea></label><button class="primary">Save invoice preferences</button></form>`;
    if(page==='Claims & invoices'){
      const model=pref.model;
      html=html.slice(0,html.indexOf('<section class="card">'))+`<section class="card"><h2>${e(model)} drafts</h2><p>Supplier: ${e(pref.supplier || 'Complete supplier legal name in Invoice preferences')} · ${pref.gstRegistered?'GST registered':'Not GST registered'} · input ${e(pref.taxBasis.toLowerCase())}</p><p>Draft only. No statutory payment claim is issued or served. <a href="https://www.building.govt.nz/projects-and-consents/why-contracts-are-valuable/construction-contracts-act-2002/other-requirements" target="_blank" rel="noopener">Review section 20 and prescribed Form 1 requirements</a>.</p><button class="secondary" data-co-pref>Change invoice preferences</button></section><form class="card co-form" id="co-adapted-claim">${f('reference','Contract / work reference','','text','required maxlength="150"')}${f('work',model==='Stage/milestone'?'Stage / milestone and work description':'Work and valuation basis','','text','required maxlength="500"')}${f('from','Work period start','','date','required')}${f('to','Work period end','','date','required')}${model==='Time & materials'?`${f('hours','Hours',0,'number','required min="0" max="1000000" step="0.01"')}${f('rate','Hourly rate',0,'number','required min="0" max="1000000" step="0.01"')}${f('materials','Materials amount',0,'number','required min="0" max="100000000" step="0.01"')}`:`${f('amount',model==='Progress valuation'?'Cumulative work valuation':model==='Fixed-price invoice'?'Agreed fixed-price amount':'This stage amount',0,'number','required min="0" max="100000000" step="0.01"')}${model==='Progress valuation'?f('previous','Previously claimed cumulative value',0,'number','required min="0" max="100000000" step="0.01"'):''}`}<p>All entered amounts use ${e(pref.taxBasis)}. ${model==='Progress valuation'?'Prior claims are deducted once from cumulative valuation.':'Use only work not already invoiced; these are current-period amounts.'}</p><button class="primary">Save ${e(model.toLowerCase())} draft</button></form><section class="card"><h2>Saved drafts</h2>${mine('claims').map(q=>{const totals=q.totals || {net:q.valuation-q.previous,gst:(q.valuation-q.previous)*q.gst/100,gross:(q.valuation-q.previous)*(1+q.gst/100)};return `<div class="co-row"><div><strong>${e(q.invoiceRef || q.reference)}</strong><p>${e(q.model || 'Progress valuation')} · ${e(q.work)}<br>Due ${e(q.due)} · net ${precise(totals.net)} · GST ${precise(totals.gst)}</p><span class="tag amber">Draft — not served</span></div><strong>${precise(totals.gross)}</strong><button class="secondary" data-co-adapted-export="${e(q.id)}">Download draft invoice / valuation</button></div>`;}).join('') || '<p>No invoice drafts yet.</p>'}</section>`;
    }
    if(page==='Pricing model')html+=`<section class="card co-notice"><h2>Spreadsheet model adapter</h2><p>Import the agreed CSV schema for a spreadsheet model under development. This is not live spreadsheet synchronisation. Costs remain UI-private only; production requires server permissions.</p><button class="secondary" id="co-template">Download fictional CSV template</button></section><form class="card co-form" id="co-model-preview"><h2>Validate a CSV model</h2>${f('source','Source / revision label','','text','required maxlength="160"')}<label>UTF-8 CSV<input name="file" type="file" accept=".csv,text/csv" required></label><p>Exact header: ${e(columns.join(', '))}. Up to 500 rows. Quantities may be zero. Unit costs exclude GST; markup applies to line cost.</p><button class="primary">Preview and validate</button></form><section class="card" id="co-model-result"><p>Select a CSV to see rows and validation errors before import.</p></section><section class="card"><h2>Imported model records</h2>${mine('contractorQuotes').filter(q=>q.pricingModel).map(q=>`<p>${e(q.itemCode)} · ${e(q.description)} · selling ${precise(q.qty*q.rate)} excluding GST<br><span class="small">${e(q.pricingModel.source)} · revision ${e(q.pricingModel.revision)} · ${e(q.pricingModel.importedAt)}</span></p>`).join('') || '<p>No model rows imported.</p>'}</section>`;
    return `<div class="co-workspace">${html}</div>`;
  }
  function bind(page,c) {
    const p=setup(c), s=c.store, root=document.querySelector('.co-workspace'); if(!root)return;
    const recordText=r=>`DRAFT PREPARATION RECORD — NOT OFFICIAL ROW\nProject: ${p.id} — ${p.name}\nBuilding owner: ${r.buildingOwner || p.client}\nSite address: ${r.siteAddress || 'Not supplied'}\nBuilding consent: ${r.consentNumber || 'Not supplied'}\nRestricted building work: ${r.work}\nPractitioner involvement: ${r.recordType || 'Not supplied'}\nPractitioner: ${r.practitioner.person}\nLBP: ${r.practitioner.lbp || 'Not supplied'}\nLicence class: ${r.practitioner.licenceClass || 'Not supplied'}\nCompletion: ${r.completedOn}\nNo signature. Each LBP must complete the official prescribed form and supply it to the building owner and territorial authority on completion of their restricted building work.`;
    const save=message=>{c.save();c.toast(message);c.navigate(page);};
    const form=(selector,handler)=>{const el=root.querySelector(selector);if(el)el.onsubmit=ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(el));handler(d);};};
    const add=(key,d)=>s[key].push({...d,id:id(),projectId:p.id});
    root.querySelector('#co-project').onchange=ev=>{c.store.contractorProjectId=ev.target.value;c.save();c.navigate(page);};
    form('#co-membership',d=>{if(!d.reviewed)return c.toast('Review the proposed terms first.');s.subscriptions.push({id:id(),business:d.business,email:d.email,status:'Interest only — no billing',monthlyExGst:s.fees?.contractorMonthly ?? null,gstRate:15,termsReviewed:true,createdAt:new Date().toISOString()});c.notify({title:'Contractor membership interest',message:d.business+' registered demo signup interest.',roles:['staff'],kind:'membership'});save('Signup interest saved; no subscription activated');});
    form('#co-invoice-pref',d=>{const dueDays=Number(d.dueDays);if(!models.includes(d.model)||!Number.isInteger(dueDays)||dueDays<0||dueDays>365||! /^[A-Za-z0-9_-]{1,20}$/.test(d.prefix))return c.toast('Check invoice preferences.');s.invoicePreferences[p.id]={...d,dueDays,gstRegistered:d.gstRegistered==='on'};save('Invoice preferences saved');});
    const prefButton=root.querySelector('[data-co-pref]');if(prefButton)prefButton.onclick=()=>c.navigate('Invoice preferences');
    form('#co-adapted-claim',d=>{try{const pref={...preferences(s,p.id)},totals=invoiceAmounts({...d,amount:d.amount || 0},pref);if(d.to<d.from||!Number.isFinite(Date.parse(d.to)))throw Error('Check work period dates.');const rid=id(),dueDate=new Date(nzToday()+'T12:00:00Z');dueDate.setUTCDate(dueDate.getUTCDate()+pref.dueDays);s.claims.push({...d,id:rid,projectId:p.id,model:pref.model,preferences:pref,totals,invoiceRef:pref.prefix+'-'+rid,issuedOn:nzToday(),due:dueDate.toISOString().slice(0,10),status:'Draft — not served',valuation:totals.net,previous:0,gst:pref.gstRegistered?15:0});save('Invoice draft saved; nothing issued');}catch(err){c.toast(err.message);}});
    root.querySelectorAll('[data-co-adapted-export]').forEach(b=>b.onclick=()=>{const q=s.claims.find(x=>x.id===b.dataset.coAdaptedExport&&x.projectId===p.id);if(!q)return;const pref=q.preferences || preferences(s,p.id),t=q.totals || {net:q.valuation-q.previous,gst:(q.valuation-q.previous)*q.gst/100,gross:(q.valuation-q.previous)*(1+q.gst/100)};download(`${p.id}-${q.id}-draft-invoice.txt`,`DRAFT INVOICE / VALUATION — NOT ISSUED OR SERVED\nReference: ${q.invoiceRef || q.id}\nProject: ${p.id} — ${p.name}\nClient: ${p.client}\nSupplier: ${pref.supplier || 'TO COMPLETE'}\nGST registered: ${pref.gstRegistered?'Yes':'No'}\nGST number: ${pref.gstRegistered?(pref.gstNumber || 'TO COMPLETE'):'Not applicable'}\nModel: ${q.model || 'Progress valuation'}\nContract/work reference: ${q.reference}\nPeriod: ${q.from} to ${q.to}\nWork: ${q.work}\nInput tax basis: ${pref.taxBasis}\nCumulative/input amount: ${q.amount || q.valuation}\nPreviously claimed (input basis): ${q.totals?.prior ?? q.previous ?? 0}\nHours/rate/materials: ${q.hours || 0} / ${q.rate || 0} / ${q.materials || 0}\nCurrent net: ${precise(t.net)}\nGST rate: ${q.gst}%\nGST: ${precise(t.gst)}\nGross: ${precise(t.gross)}\nDue: ${q.due}\nTerms: ${pref.terms}\nPayment details: TO COMPLETE AND VERIFY\nThis draft is not served as a statutory claim. Review Construction Contracts Act section 20, prescribed Form 1 and contractual service requirements before issuing a statutory claim.`);});
    const template=root.querySelector('#co-template');if(template)template.onclick=()=>download('fictional-pricing-model-template.csv',columns.join(',')+'\r\nDEMO-001,Fictional frame labour,Labour,hour,40,50,20\r\nDEMO-002,Fictional fasteners,Materials,box,2,25.50,15\r\n','text/csv;charset=utf-8');
    form('#co-model-preview',async d=>{const input=root.querySelector('#co-model-preview input[type=file]'),file=input.files[0],out=root.querySelector('#co-model-result');if(!file||file.size>1000000)return c.toast('Choose a CSV under 1 MB.');try{const bytes=await file.arrayBuffer(),text=new TextDecoder('utf-8',{fatal:true}).decode(bytes),parsed=parsePricingCSV(text),e=c.escape;out.innerHTML=`<h2>Model preview</h2><p>Source ${e(d.source)} · ${e(file.name)} · ${parsed.rows.length} rows</p>${parsed.errors.length?`<ul>${parsed.errors.slice(0,30).map(x=>`<li>${e(x)}</li>`).join('')}</ul><p>Correct all errors before importing.</p>`:`<p>Validation passed. Cost ${precise(parsed.rows.reduce((n,x)=>n+x.cost,0))} · selling ${precise(parsed.rows.reduce((n,x)=>n+x.selling,0))} excluding GST · GST ${precise(parsed.rows.reduce((n,x)=>n+x.gst,0))}</p><div class="table-wrap"><table><thead><tr><th>Code / description</th><th>Quantity</th><th>Cost</th><th>Selling ex GST</th><th>GST</th></tr></thead><tbody>${parsed.rows.map(x=>`<tr><td>${e(x.item_code)} · ${e(x.description)}</td><td>${x.quantity}</td><td>${precise(x.cost)}</td><td>${precise(x.selling)}</td><td>${precise(x.gst)}</td></tr>`).join('')}</tbody></table></div><button class="primary" id="co-model-import">Import validated rows</button>`}`;const button=out.querySelector('#co-model-import');if(button)button.onclick=()=>{const date=new Date().toISOString();parsed.rows.forEach(x=>{const known=s.contractorQuotes.find(q=>q.projectId===p.id&&q.itemCode===x.item_code&&q.pricingModel),record={description:x.description,category:x.category,unit:x.unit,itemCode:x.item_code,qty:x.quantity,rate:x.quantity>0?x.selling/x.quantity:x.unit_cost_ex_gst*(1+x.markup_percent/100),costRate:x.unit_cost_ex_gst,markup:x.markup_percent,sharing:'private',pricingModel:{source:d.source,revision:d.source,file:file.name,importedAt:date,schema:'sh-pricing-csv-v1'}};if(known)Object.assign(known,record);else add('contractorQuotes',record);});save('Validated model rows imported; existing manual lines retained');};}catch(err){c.toast('Could not read UTF-8 CSV: '+err.message);}});
    form('#co-quote',d=>{d.qty=Number(d.qty);d.rate=Number(d.rate);if(!Number.isFinite(d.qty*d.rate)||d.qty<=0||d.rate<0)return c.toast('Enter valid positive quantities and non-negative rates.');add('contractorQuotes',d);save('Private demo cost line saved');});
    form('#co-claim',d=>{['valuation','previous','gst'].forEach(k=>d[k]=Number(d[k]));if(d.to<d.from||d.due<d.to||d.previous>d.valuation||!Number.isFinite(d.valuation+d.previous+d.gst))return c.toast('Check claim dates and valuation. Prior claims cannot exceed cumulative value.');add('claims',{...d,status:'Draft — not served'});save('Draft valuation saved; nothing issued');});
    form('#co-task',d=>{d.plannedHours=Number(d.plannedHours);d.actualHours=Number(d.actualHours);if(d.end<d.start||!Number.isFinite(d.actualHours+d.plannedHours))return c.toast('Check task dates and hours.');add('tasks',{...d,complete:false});save('Scope task added');});
    root.querySelectorAll('[data-co-task]').forEach(el=>el.onsubmit=ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(el)),t=s.tasks.find(x=>x.id===el.dataset.coTask);t.actualHours=Number(d.actualHours);t.mode=d.mode;t.complete=d.complete==='on';if(!Number.isFinite(t.actualHours)||t.actualHours<0)return c.toast('Check hours.');save('Task progress updated');});
    form('#co-person',d=>{add('businessProfiles',d);save('Team record saved for verification');});
    form('#co-row',d=>{const practitioner=s.businessProfiles.find(x=>x.id===d.practitioner&&x.projectId===p.id);if(!practitioner||!d.reviewed||!d.confirmed||d.completedOn>nzToday())return c.toast('Choose a practitioner and confirm completed work with a valid completion date.');add('rowDrafts',{...d,practitioner:{...practitioner},reviewed:true,confirmed:true,released:false});save('Reviewed completion draft saved');});
    root.querySelectorAll('[data-co-remove]').forEach(b=>b.onclick=()=>{const [key,rid]=b.dataset.coRemove.split(':');s[key]=s[key].filter(x=>x.id!==rid||x.projectId!==p.id);save('Cost line removed');});
    root.querySelectorAll('[data-co-release]').forEach(b=>b.onclick=()=>{const r=s.rowDrafts.find(x=>x.id===b.dataset.coRelease&&x.projectId===p.id);if(!r||!r.reviewed||!r.confirmed)return c.toast('Review and practitioner confirmation are required.');r.released=true;add('documents',{name:`Completion draft — ${r.practitioner.person}`,type:'Completion record draft',status:'Shared draft — official ROW still required',version:1,url:'',visibility:['staff','customer','contractor'],uploadedAt:new Date().toISOString(),content:recordText(r)});c.notify({title:'Completion record draft available',message:`${p.name}: reviewed completion draft shared. Official prescribed ROW must be provided separately.`,roles:['staff','customer'],projectId:p.id,kind:'document'});save('Completion draft shared independently of payment');});
    root.querySelectorAll('[data-co-invoice]').forEach(b=>b.onclick=()=>{const q=s.claims.find(x=>x.id===b.dataset.coInvoice&&x.projectId===p.id);if(!q)return;const net=q.valuation-q.previous,gst=net*q.gst/100,text=`DRAFT INVOICE / VALUATION — NOT ISSUED OR SERVED\nDraft reference: ${q.id}\nProject: ${p.id} — ${p.name}\nClient: ${p.client}\nContract / work reference: ${q.reference}\nPeriod: ${q.from} to ${q.to}\nWork and valuation basis: ${q.work}\nCumulative value excluding GST: NZD ${Number(q.valuation).toFixed(2)}\nPreviously claimed excluding GST: NZD ${Number(q.previous).toFixed(2)}\nCurrent net: NZD ${net.toFixed(2)}\nGST rate: ${q.gst}%\nGST amount: NZD ${gst.toFixed(2)}\nCurrent gross: NZD ${(net+gst).toFixed(2)}\nProposed due date: ${q.due}\nSupplier legal name, GST registration status/number where applicable, and payment details: TO COMPLETE AND VERIFY.\nThis is a draft valuation, not a statutory payment claim served under the Construction Contracts Act. Review section 20 requirements, the current prescribed Form 1 notice and contract/service requirements before issuing any statutory claim. No payment instruction or claim has been sent.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=`${p.id}-${q.id}-draft-invoice.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
    root.querySelectorAll('[data-co-download]').forEach(b=>b.onclick=()=>{const r=s.rowDrafts.find(x=>x.id===b.dataset.coDownload&&x.projectId===p.id);if(!r)return;const text=recordText(r);const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=`${p.id}-completion-draft.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  }
  window.SHContractor={pages,render,bind,parsePricingCSV,invoiceAmounts};
})();
